const validItems = $input.all().filter(item => {
  const data = item.json?.body?.data || {};
  const key = data.key || {};
  const message = data.message || {};

  const isEcho = key.fromMe === true;
  const remoteJid = key.remoteJid || '';
  const isGroup = remoteJid.endsWith('@g.us');
  const isStatus = remoteJid === 'status@broadcast';

  const hasText = !!(message.conversation || message.extendedTextMessage?.text);
  const hasImage = !!message.imageMessage;
  const hasAudio = !!message.audioMessage;
  const hasSupportedContent = hasText || hasImage || hasAudio;

  return !isEcho && !isGroup && !isStatus && hasSupportedContent;
});

return validItems;

const data = $json.body.data;
const key = data.key || {};
const message = data.message || {};

const numero = (key.remoteJid || '').split('@')[0];
const nome = data.pushName || '';

let tipo_mensagem = null;
let texto = '';
let legenda = '';
let mimetype = null;

if (message.conversation || message.extendedTextMessage?.text) {
  tipo_mensagem = 'texto';
  texto = message.conversation || message.extendedTextMessage.text;
} else if (message.imageMessage) {
  tipo_mensagem = 'imagem';
  mimetype = (message.imageMessage.mimetype || 'image/jpeg').split(';')[0];
  // Legenda que o usuario escreveu junto com a foto (ex: "essa imagem e real?") .
  // Sem isso, o Gemini so ve a imagem pura, sem saber o que a pessoa esta perguntando.
  legenda = message.imageMessage.caption || '';
} else if (message.audioMessage) {
  tipo_mensagem = 'audio';
  mimetype = (message.audioMessage.mimetype || 'audio/ogg').split(';')[0];
}

// Corpo pronto para a chamada POST /chat/getBase64FromMediaMessage da Evolution API,
// usado so quando tipo_mensagem for imagem/audio (montado aqui, em JS puro, para nao
// depender do parser de expressao do n8n com objetos aninhados).
const mediaFetchBody = {
  message: { key, message },
  convertToMp4: false
};

return [{
  json: {
    numero,
    nome,
    tipo_mensagem,
    texto,
    legenda,
    mimetype,
    mediaFetchBody
  }
}];

// Reconstroi o item com os dados extraidos originalmente + o base64 obtido da Evolution API.
const extraido = $('Extracao - Dados e Tipo').item.json;
const resposta = $json;

// A Evolution API pode devolver um `mimetype` proprio na resposta (varia por versao),
// mas ele vem sem sanitizar (ex: "audio/ogg; codecs=opus"), e a API do Gemini rejeita
// mimeType com esse sufixo de codec. Sempre limpamos aqui, seja o valor vindo da
// resposta ou o ja detectado na extracao (fallback).
const mimetypeBruto = resposta.mimetype || extraido.mimetype || '';
const mimetype = mimetypeBruto.split(';')[0].trim();

return [{
  json: {
    numero: extraido.numero,
    nome: extraido.nome,
    tipo_mensagem: extraido.tipo_mensagem,
    texto: '',
    legenda: extraido.legenda || '',
    mimetype,
    base64: resposta.base64
  }
}];

// Monta o array `parts` (texto ou midia em base64) e o corpo completo da chamada
// ao Gemini. Feito inteiramente em JS (Code node) em vez de na expressao do node
// HTTP Request seguinte, porque o parser de expressao do n8n nao lida bem com
// objetos JSON grandes/aninhados escritos diretamente no campo do node.
const item = $json;
let parts;

if (item.tipo_mensagem === 'texto') {
  parts = [{ text: `Mensagem recebida do usuario para analise:\n\n${item.texto}` }];
} else if (item.tipo_mensagem === 'imagem') {
  const legendaTexto = item.legenda
    ? `O usuario escreveu esta legenda/pergunta junto com a foto: "${item.legenda}"`
    : 'O usuario nao escreveu nenhuma legenda ou pergunta junto com a foto.';
  parts = [
    { text: `O usuario enviou este print de tela ou foto para analise. ${legendaTexto} Descreva o que ve (remetente, valores, links, layout, pessoas, contexto do evento) e classifique - considere tambem se pode ser uma imagem tirada de contexto, montada ou usada para espalhar informacao falsa.` },
    { inlineData: { mimeType: item.mimetype || 'image/jpeg', data: item.base64 } }
  ];
} else {
  parts = [
    { text: 'O usuario enviou este audio com um relato falado para analise. Entenda o relato e classifique.' },
    { inlineData: { mimeType: item.mimetype || 'audio/ogg', data: item.base64 } }
  ];
}

// Fonte da verdade documentada e revisavel em prompts/antigolpe_system_prompt.md
// (manter os dois em sincronia ao editar um dos dois).
const systemPrompt = 'Voce e um assistente especializado em ajudar pessoas idosas no Brasil a identificar golpes digitais E fake news/desinformacao recebidos por WhatsApp - mensagens de texto, prints de tela (cobrancas, conversas, anuncios, SMS, noticias, fotos), e audios com relatos falados pelo proprio usuario.\n\n' +
  'Seu publico nao tem familiaridade tecnica. Muitos nunca ouviram termos como "phishing", "engenharia social" ou "IA generativa" - e nao devem precisar ouvir isso de voce. Voce nunca conversa como um robo nem como um especialista em seguranca; voce explica como uma pessoa de confianca explicaria para um familiar mais velho, com calma e sem alarmismo desnecessario. Voce NUNCA age sozinho no lugar do usuario (nao liga para bancos, nao clica em links, nao envia dinheiro) - sua unica funcao e analisar e explicar em linguagem simples.\n\n' +
  'Quando receber uma IMAGEM (print de tela): descreva primeiro, para si mesmo, o que esta escrito e visivel (remetente, valores, links, botoes, layout) e so entao classifique com base nisso. Quando receber um AUDIO: entenda o relato da pessoa e classifique com base nele.\n\n' +
  'CATEGORIAS A IDENTIFICAR - golpes financeiros E desinformacao/fake news (nao exaustiva, use julgamento para casos parecidos):\n' +
  '- Phishing: links encurtados ou com dominio estranho, urgencia artificial ("sua conta sera bloqueada"), pedido para "confirmar dados".\n' +
  '- Boleto falso/adulterado: codigo de barras nao confere com o valor, valor fora do padrao esperado, origem nao clara.\n' +
  '- Falsa promocao/premio: "voce ganhou", "clique para resgatar", sorteio que a pessoa nao lembra de ter participado, pedido de "taxa" para liberar premio.\n' +
  '- Golpe do parente/emergencia: pedido urgente de dinheiro (PIX, recarga, boleto) alegando ser filho(a)/neto(a)/parente em apuros, geralmente com pressa e numero novo/desconhecido.\n' +
  '- Golpe do PIX: chave PIX diferente da esperada, cobranca fora de contexto, pedido de PIX "de teste" ou "para desbloquear conta".\n' +
  '- Falso funcionario de banco/INSS/Correios: pedido de senha, codigo de verificacao (SMS/token), dados de cartao, ou instalacao de app de "suporte remoto" - instituicoes oficiais nunca pedem isso por telefone/WhatsApp.\n' +
  '- Fake news/desinformacao: fotos ou videos tirados de contexto (imagem real de um evento, mas legenda mentindo sobre quem/quando/o que aconteceu), montagens ou imagens editadas, boatos de saude (curas milagrosas, remedios falsos), boatos politicos, noticias inventadas se passando por veiculo de imprensa real, correntes de WhatsApp alarmistas sem fonte confiavel. Classifique como "golpe" (tipo_golpe "fake_news") quando a informacao for claramente falsa ou manipulada, e como "suspeito" quando parecer fora de contexto mas sem certeza suficiente para afirmar.\n\n' +
  'NIVEL DE CONFIANCA - REGRA DE OURO: nunca afirme com certeza absoluta que algo e 100% seguro. Use "alta" quando os sinais forem claros e multiplos; "media" quando houver sinais de atencao mas nao for conclusivo; "baixa" quando faltar contexto para avaliar bem. Sempre que a confianca for "baixa" ou o conteudo for ambiguo, a classificacao NUNCA deve ser "seguro" sem ressalva - use "suspeito" ou "indeterminado", com recomendacao de cautela (confirmar por telefone oficial, nao clicar, pedir ajuda a alguem de confianca).\n\n' +
  'Responda SEMPRE no formato JSON estruturado solicitado. Regras de conteudo para explicacao_simples e recomendacao: nunca usar as palavras "phishing", "engenharia social", "IA", "inteligencia artificial", "algoritmo" ou jargao tecnico equivalente; frases curtas, diretas, tom acolhedor, como alguem explicando para um familiar; recomendacao deve ser sempre uma acao concreta (ex: "nao clique nesse link", "ligue para o banco pelo numero que esta no cartao, nunca pelo numero que te mandaram a mensagem", "confirme com a pessoa por uma ligacao de video antes de mandar qualquer dinheiro", "nao passe senha nem codigo de confirmacao para ninguem", "nao encaminhe essa foto/video para mais ninguem antes de confirmar se e verdade em um site de noticias confiavel"). Quando classificacao for "seguro", ainda assim inclua uma recomendacao leve de bom senso.\n\n' +
  'Voce nao tem acesso a internet nem consegue verificar links de verdade - avalie so pela aparencia/padrao, nunca confirme com certeza que um link especifico e seguro. Nunca invente detalhes que nao foram informados na mensagem. Se o conteudo nao tiver nada para analisar (ex: mensagem vazia ou pergunta generica sem anexo), responda classificacao "indeterminado", confianca "baixa", e peca para a pessoa encaminhar a mensagem, print ou audio original.';

const geminiBody = {
  systemInstruction: { parts: [{ text: systemPrompt }] },
  contents: [{ role: 'user', parts }],
  generationConfig: {
    temperature: 0.2,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        classificacao: { type: 'STRING', enum: ['golpe', 'suspeito', 'seguro', 'indeterminado'] },
        tipo_golpe: { type: 'STRING', enum: ['phishing', 'boleto_falso', 'falsa_promocao', 'golpe_parente', 'golpe_pix', 'falso_funcionario', 'fake_news', 'outro'], nullable: true },
        confianca: { type: 'STRING', enum: ['alta', 'media', 'baixa'] },
        explicacao_simples: { type: 'STRING' },
        recomendacao: { type: 'STRING' }
      },
      required: ['classificacao', 'confianca', 'explicacao_simples', 'recomendacao']
    }
  }
};

return [{
  json: {
    numero: item.numero,
    nome: item.nome,
    tipo_mensagem: item.tipo_mensagem,
    texto: item.texto,
    geminiBody
  }
}];

// A resposta do Gemini vem em candidates[0].content.parts[0].text como uma STRING JSON
// (porque pedimos responseMimeType: application/json). Fazemos o parse e aplicamos uma
// rede de seguranca extra: nunca deixar sair "seguro" quando a confianca for "baixa".
const body = $json;
const raw = body?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = {
    classificacao: 'indeterminado',
    tipo_golpe: null,
    confianca: 'baixa',
    explicacao_simples: 'Nao consegui analisar com certeza esse conteudo.',
    recomendacao: 'Por seguranca, nao clique em nada nem passe nenhum dado ate confirmar por telefone.'
  };
}

// Rede de seguranca: nunca "seguro" com confianca baixa.
if (parsed.classificacao === 'seguro' && parsed.confianca === 'baixa') {
  parsed.classificacao = 'suspeito';
}

const origem = $('Montar Conteudo Gemini').item.json;

return [{
  json: {
    numero: origem.numero,
    nome: origem.nome,
    tipo_mensagem: origem.tipo_mensagem,
    texto: origem.texto,
    classificacao: parsed.classificacao || 'indeterminado',
    tipo_golpe: parsed.tipo_golpe || null,
    confianca: parsed.confianca || 'baixa',
    explicacao_simples: parsed.explicacao_simples || '',
    recomendacao: parsed.recomendacao || ''
  }
}];

// Chamada ao Gemini falhou (erro de rede, timeout, quota etc). Resposta cautelosa
// por padrao: nunca dizer que esta tudo bem quando nao conseguimos nem analisar.
const origem = $('Montar Conteudo Gemini').item.json;

return [{
  json: {
    numero: origem.numero,
    nome: origem.nome,
    tipo_mensagem: origem.tipo_mensagem,
    texto: origem.texto,
    classificacao: 'indeterminado',
    tipo_golpe: null,
    confianca: 'baixa',
    explicacao_simples: 'Nao consegui analisar esse conteudo agora - pode ter sido um problema tecnico passageiro.',
    recomendacao: 'Por seguranca, nao clique em nada, nao pague nada e nao passe nenhum dado ate confirmar diretamente por telefone com a instituicao ou pessoa envolvida. Pode me mandar de novo em alguns minutos.'
  }
}];

// O hash do numero (SHA-256) e calculado depois, direto no SQL do node de log
// (Postgres tem a funcao sha256() nativa desde a v11). O sandbox de execucao do
// n8n (JS Task Runner) bloqueia require('crypto') e nao expoe Web Crypto global,
// entao evitamos fazer hash aqui.
const item = $json;

const emojiPorClassificacao = {
  golpe: '\ud83d\udea8',
  suspeito: '\u26a0\ufe0f',
  seguro: '\u2705',
  indeterminado: '\ud83e\udd14'
};
const tituloPorClassificacao = {
  golpe: 'Isso parece um GOLPE',
  suspeito: 'Melhor ter cuidado com isso',
  seguro: 'Nao encontrei sinais de golpe',
  indeterminado: 'Nao consegui ter certeza'
};

const emoji = emojiPorClassificacao[item.classificacao] || '\ud83e\udd14';
const titulo = tituloPorClassificacao[item.classificacao] || 'Nao consegui ter certeza';

const mensagem = `${emoji} *${titulo}*\n\n${item.explicacao_simples}\n\n\ud83d\udc49 ${item.recomendacao}\n\n_Mensagem automatica do AntiGolpe. Na duvida, sempre vale pedir ajuda a alguem de confianca._`;

// Resumo curto do conteudo para o log (sem gravar o texto completo de audios/imagens,
// so um trecho do texto quando for mensagem de texto).
let conteudo_resumido;
if (item.tipo_mensagem === 'texto') {
  conteudo_resumido = (item.texto || '').slice(0, 300);
} else {
  conteudo_resumido = `[${item.tipo_mensagem} recebido - conteudo nao textual]`;
}

return [{
  json: {
    numero: item.numero,
    mensagem_final: mensagem,
    tipo_mensagem: item.tipo_mensagem,
    conteudo_resumido,
    classificacao: item.classificacao,
    tipo_golpe: item.tipo_golpe,
    confianca: item.confianca,
    explicacao_simples: item.explicacao_simples
  }
}];
